import { readdir, readFile, stat } from "node:fs/promises";
import { join } from "node:path";

import type { Db } from "../db.js";
import type { RunDetail, RunListItem } from "../types.js";

/** Run ids are generated by quantlab.research.runs.save: 20261014-184855-35b3c9. */
const RUN_ID = /^[0-9]{8}-[0-9]{6}-[0-9a-f]{6}$/;

export function isRunId(id: string): boolean {
  return RUN_ID.test(id);
}

async function readJson<T>(path: string): Promise<T | null> {
  try {
    return JSON.parse(await readFile(path, "utf8")) as T;
  } catch {
    return null;
  }
}

const num = (v: unknown): number | null => (typeof v === "number" && Number.isFinite(v) ? v : null);

/** Reads the run directories that quantlab.research.runs writes. */
export class RunStore {
  constructor(
    private readonly home: string,
    private readonly db: Db,
  ) {}

  private get root(): string {
    return join(this.home, "runs");
  }

  async ids(): Promise<string[]> {
    try {
      const names = await readdir(this.root);
      return names.filter(isRunId).sort().reverse();
    } catch {
      return [];
    }
  }

  /** A run is listed once its summary is written, so a half-saved run never shows. */
  async item(id: string): Promise<RunListItem | null> {
    if (!isRunId(id)) return null;
    const dir = join(this.root, id);
    const [m, s, p] = await Promise.all([
      readJson<Record<string, unknown>>(join(dir, "manifest.json")),
      readJson<Record<string, unknown>>(join(dir, "summary.json")),
      readJson<Record<string, unknown>>(join(dir, "portfolio.json")),
    ]);
    if (!m || !s) return null;
    return {
      id,
      name: String(m.name ?? id),
      strategy: String(m.strategy ?? ""),
      study: String(m.study ?? ""),
      created: String(m.created_utc ?? ""),
      code: (m.code as string) ?? null,
      trades: num(s.trades),
      day_t: num(s.day_t),
      calendar_sharpe: num(s.calendar_sharpe),
      total_return: num(p?.total_return),
      final_equity: num(p?.final_equity),
    };
  }

  async list(): Promise<RunListItem[]> {
    const items = await Promise.all((await this.ids()).map((id) => this.item(id)));
    return items.filter((r): r is RunListItem => r !== null);
  }

  async detail(id: string): Promise<RunDetail | null> {
    const item = await this.item(id);
    if (!item) return null;
    const dir = join(this.root, id);
    const manifest = (await readJson<Record<string, unknown>>(join(dir, "manifest.json")))!;
    const summary = (await readJson<Record<string, unknown>>(join(dir, "summary.json")))!;
    const portfolio = await readJson<Record<string, unknown>>(join(dir, "portfolio.json"));

    let equity: [number, number][] = [];
    const eqFile = join(dir, "equity.parquet");
    if (await exists(eqFile)) {
      // pandas writes the series index as __index_level_0__; keep each UTC day's last bar
      const rows = await this.db.query<{ t: number; equity: number }>(
        `SELECT epoch_ms(max(__index_level_0__)) AS t, arg_max(equity, __index_level_0__) AS equity
           FROM read_parquet($f) GROUP BY date_trunc('day', __index_level_0__) ORDER BY t`,
        { f: eqFile },
      );
      equity = rows.map((r) => [r.t, r.equity]);
    }

    let exits: RunDetail["exits"] = [];
    let symbols: RunDetail["symbols"] = [];
    const posFile = join(dir, "positions.parquet");
    if (await exists(posFile)) {
      exits = await this.db.query(
        `SELECT coalesce(exit, 'open') AS exit, count(*) AS trades, avg(net_bp) AS mean_bp
           FROM read_parquet($f) GROUP BY 1 ORDER BY trades DESC`,
        { f: posFile },
      );
      symbols = await this.db.query(
        `SELECT symbol, count(*) AS trades, sum(net_bp) AS net_bp
           FROM read_parquet($f) GROUP BY 1 ORDER BY net_bp DESC`,
        { f: posFile },
      );
    }
    return { ...item, manifest, summary, portfolio, equity, exits, symbols };
  }
}

async function exists(path: string): Promise<boolean> {
  try {
    await stat(path);
    return true;
  } catch {
    return false;
  }
}
